import { expect, it } from "bun:test"
import { spawnSync } from "node:child_process"
import { mkdtempSync, rmSync } from "node:fs"
import { tmpdir } from "node:os"
import { join, resolve } from "node:path"
import { pathToFileURL } from "node:url"

const repoRoot = resolve(import.meta.dir, "../..")
const ffiLoadError =
  "bun-ffi-structs pointer operations require Bun or Node.js 26.1+ with node:ffi enabled (--experimental-ffi)."
const nodeFfiProbe = spawnSync(
  "node",
  ["--experimental-ffi", "--input-type=module", "-e", 'await import("node:ffi")'],
  {
    cwd: repoRoot,
    stdio: "pipe",
  },
)
const supportsNodeFfi = nodeFfiProbe.status === 0

if (process.env.REQUIRE_NODE_FFI === "1" && !supportsNodeFfi) {
  throw new Error(`REQUIRE_NODE_FFI=1 but the configured Node.js does not support node:ffi: ${nodeFfiProbe.stderr}`)
}

it("imports in Node without node:ffi until pointer helpers are used", () => {
  const tempDir = mkdtempSync(join(tmpdir(), "bun-ffi-structs-node-import-"))

  try {
    const build = spawnSync("bun", ["build", "src/index.ts", "--outdir", tempDir, "--target", "node"], {
      cwd: repoRoot,
      stdio: "pipe",
    })

    expect(build.status).toBe(0)

    const indexUrl = pathToFileURL(join(tempDir, "index.js")).href
    const script = `
      const { defineStruct } = await import(${JSON.stringify(indexUrl)})
      const PrimitiveStruct = defineStruct([["value", "u32"]])
      const packed = PrimitiveStruct.pack({ value: 123 })
      const unpacked = PrimitiveStruct.unpack(packed)
      if (unpacked.value !== 123) {
        throw new Error("primitive struct packing failed")
      }

      const TextStruct = defineStruct([
        ["text", "char*"],
        ["textLen", "u64", { lengthOf: "text" }],
      ])

      let pointerFailed = false
      try {
        TextStruct.pack({ text: "hello" })
      } catch (error) {
        pointerFailed = error instanceof Error && error.message.includes(${JSON.stringify(ffiLoadError)})
      }

      if (!pointerFailed) {
        throw new Error("expected pointer-backed packing to fail with the unsupported backend error")
      }
    `

    const node = spawnSync("node", ["--input-type=module", "-e", script], {
      cwd: repoRoot,
      stdio: "pipe",
    })

    expect(node.status).toBe(0)
  } finally {
    rmSync(tempDir, { recursive: true, force: true })
  }
})

it("falls back when Node disables string code generation", () => {
  const tempDir = mkdtempSync(join(tmpdir(), "bun-ffi-structs-node-no-codegen-"))

  try {
    const build = spawnSync("bun", ["build", "src/index.ts", "--outdir", tempDir, "--target", "node"], {
      cwd: repoRoot,
      stdio: "pipe",
    })
    expect(build.status).toBe(0)

    const indexUrl = pathToFileURL(join(tempDir, "index.js")).href
    const script = `
      const { defineStruct } = await import(${JSON.stringify(indexUrl)})
      const TestStruct = defineStruct([["value", "u32"]])
      const values = Array.from({ length: 256 }, (_, value) => ({ value }))
      for (let index = 0; index < 300; index++) {
        const packed = TestStruct.pack({ value: index })
        if (TestStruct.unpack(packed).value !== index) throw new Error("single fallback failed")
      }
      const packedList = TestStruct.packList(values)
      const unpackedList = TestStruct.unpackList(packedList, values.length)
      if (unpackedList[255].value !== 255) throw new Error("list fallback failed")
      const reused = new ArrayBuffer(TestStruct.size * values.length)
      const reusedView = new DataView(reused)
      for (let index = 0; index < 300; index++) TestStruct.packInto({ value: index }, reusedView, 0)
      TestStruct.packListInto(values, reusedView, 0)
      const target = {}
      for (let index = 0; index < 300; index++) TestStruct.unpackInto(reusedView, target)
      if (target.value !== 0) throw new Error("unpackInto fallback failed")
      const ReducedStruct = defineStruct([["value", "u32"], ["reserved", "u32", { default: 0 }]], {
        reduceValue: ({ value }) => ({ value }),
      })
      const reduced = ReducedStruct.unpackList(ReducedStruct.packList(values), values.length)
      if (reduced[255].value !== 255) throw new Error("reducer fallback failed")
    `
    const node = spawnSync("node", ["--disallow-code-generation-from-strings", "--input-type=module", "-e", script], {
      cwd: repoRoot,
      stdio: "pipe",
    })
    expect(node.status, node.stderr.toString()).toBe(0)
  } finally {
    rmSync(tempDir, { recursive: true, force: true })
  }
})

