  it("should verify byte length accuracy for complex unicode strings", () => {
    const StringStruct = defineStruct([
      ["data", "char*"],
      ["length", "u64", { lengthOf: "data" }],
    ] as const)

    const testCases = [
      { str: "Hello", expectedBytes: 5 },
